{
  "scenario": "Обслуживание клиентов с нарушением порядка (без проверки документов) и оставление ценностей без присмотра",
  "timeline": [
    {
      "t": 0.0,
      "event": "Кассир сидит за рабочим столом, помещение пустое."
    },
    {
      "t": 2.0,
      "event": "В помещение входит клиент (мужчина в белой рубашке), закрывает за собой дверь."
    },
    {
      "t": 6.0,
      "event": "Клиент кладёт на стол документ и передаёт кассиру пачку наличных. Кассир принимает деньги, не проводя видимых действий по проверке документа."
    },
    {
      "t": 10.0,
      "event": "Кассир использует счётную машину для пересчёта наличных в присутствии клиента."
    },
    {
      "t": 23.0,
      "event": "Клиент встаёт и выходит из помещения. На столе остаётся пачка наличных и документ."
    },
    {
      "t": 28.0,
      "event": "Кассир остаётся сидеть за столом, не убирая оставленные клиентом ценности. Дверь открыта."
    },
    {
      "t": 33.0,
      "event": "В помещение входит второй клиент. Кассир продолжает сидеть, ценности первого клиента всё ещё лежат на столе."
    },
    {
      "t": 36.0,
      "event": "Второй клиент передаёт наличные. Кассир начинает пересчёт, не убрав деньги предыдущего клиента."
    },
    {
      "t": 51.0,
      "event": "Второй клиент выходит. На столе снова остаются наличные и документ. Кассир не убирает их."
    },
    {
      "t": 58.0,
      "event": "Видео заканчивается, ценности лежат на столе, дверь открыта."
    }
  ],
  "violations": [
    {
      "type_id": "no_client_id_check",
      "timecode_sec": 6.0,
      "confidence": 0.75,
      "observed": "Клиент кладёт документ на стол и передаёт деньги, кассир сразу начинает пересчёт, не проводя видимых действий по проверке документа (не смотрит на него, не сверяет с экраном)."
    },
    {
      "type_id": "cash_unattended",
      "timecode_sec": 23.0,
      "confidence": 0.95,
      "observed": "Клиент выходит из помещения, оставив на столе пачку наличных и документ. Кассир не убирает ценности в сейф или ящик, а продолжает сидеть за столом. На момент входа следующего клиента (t=33.0) деньги первого клиента всё ещё лежат на столе."
    },
    {
      "type_id": "foreign_cash_on_desk",
      "timecode_sec": 33.0,
      "confidence": 0.95,
      "observed": "В помещение входит второй клиент и начинает обслуживаться, при этом пачка наличных первого клиента всё ещё открыто лежит на рабочем столе и не убрана в сейф/ящик."
    },
    {
      "type_id": "door_left_open",
      "timecode_sec": 23.0,
      "confidence": 0.9,
      "observed": "Клиент выходит из кассового узла, дверь остаётся открытой (распахнутой). Кассир не закрывает её, в таком состоянии дверь находится до конца видео."
    }
  ]
}
